Dados do cliente:
{{ JSON.stringify($json, null, 2) }}

parameters.jsCode:
// Pega CSv como texto vinda do HTTP Request 
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw == "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean); const headers = lines[0].split(",").map(h => h.trim()); 

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {}; 
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

// nornaliza minimo para nómero
  obj.minimo = Number(String(obj.minino).replace(/[^\d]/g, "")) || 0;
  return obj;
});
return [{json : {investimentos} }];

const entrada = $input.first().json;

// Extrai os dados dos caminhos corretos
const clientes = entrada.body?.clientes ?? [];
const investimentos = entrada.investimentos ?? [];

// Converte valores como "R$ 12.500,00" em números
function converterSaldo(valor) {
  if (typeof valor === "number") return valor;

  return Number(
    String(valor)
      .replace(/[^\d,.-]/g, "")
      .replace(/\./g, "")
      .replace(",", ".")
  );
}

// Verifica se os dados chegaram corretamente
if (clientes.length === 0 || investimentos.length === 0) {
  return [{
    json: {
      erro: "Clientes ou investimentos não encontrados.",
      clientesEncontrados: clientes.length,
      investimentosEncontrados: investimentos.length
    }
  }];
}

// Gera uma saída para cada cliente
return clientes.map(cliente => {
  const saldo = converterSaldo(cliente.saldo);

  const produtos = investimentos.filter(produto =>
    produto.perfil === cliente.perfil &&
    saldo >= Number(produto.minimo || 0)
  );

  const listaProdutos = produtos.length
    ? produtos.map(produto =>
        `• ${produto.produto} — Rentabilidade informada: ${produto.rentabilidade}`
      ).join("\n")
    : "No momento, não encontramos produtos para os critérios informados.";

  const mensagem = `Olá, ${cliente.nome}! Tudo bem?

Com base no seu perfil ${cliente.perfil}, separamos algumas opções de investimento para você conhecer:

${listaProdutos}

Antes de investir, avalie os riscos, os custos, a liquidez e a adequação de cada produto aos seus objetivos. Rentabilidades passadas ou estimadas não garantem resultados futuros.

Esta mensagem é informativa e não constitui recomendação individual de investimento.`;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo,
      perfil: cliente.perfil,
      quantidade_produtos: produtos.length,
      produtos_recomendados: produtos.map(p => p.produto),
      mensagem
    }
  };
});

return $input.all().map(item => {
  const dados = item.json;

  return {
    json: {
      cliente: {
        nome: dados.nome,
        email: dados.email,
        perfil_investidor: dados.perfil,
        saldo_disponivel: dados.saldo,
        moeda: "BRL"
      },

      investimentos_disponiveis: (
        dados.produtos_recomendados ?? []
      ).map(produto => ({
        nome: produto,
        perfil: dados.perfil
      })),

      contexto: {
        objetivo: "Criar uma mensagem personalizada e informativa para o cliente.",
        quantidade_opcoes: dados.quantidade_produtos ?? 0,
        observacao:
          "Não garantir rentabilidade, não inventar informações sobre produtos e não presumir que o cliente deva investir todo o saldo."
      }
    }
  };
});

return $input.all().map(item => {
  const dados = item.json;

  // Extrai o texto retornado pelo Gemini
  const texto = (
    dados.content?.parts?.[0]?.text ??
    dados.text ??
    dados.output ??
    dados.response ??
    ""
  ).trim();

  if (!texto) {
    return {
      json: {
        erro: "A IA não retornou conteúdo para o e-mail.",
        dados_recebidos: dados
      }
    };
  }

  // Remove blocos Markdown, caso existam
  const textoLimpo = texto
    .replace(/^```(?:text|markdown)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  // Separa assunto e corpo
  const correspondencia = textoLimpo.match(
    /^\s*(?:\*\*)?Assunto\s*:\s*(.*?)(?:\*\*)?\s*$/im
  );

  const assunto = correspondencia
    ? correspondencia[1].replace(/\*\*/g, "").trim()
    : "Informações sobre investimentos";

  let corpo = textoLimpo;

  if (correspondencia) {
    corpo = textoLimpo.replace(correspondencia[0], "").trim();
  }

  // Remove formatação Markdown residual
  corpo = corpo
    .replace(/\*\*(.*?)\*\*/g, "$1")
    .replace(/__(.*?)__/g, "$1")
    .replace(/^\s*[-*]\s+/gm, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

  return {
    json: {
      email_destinatario:
        dados.email ??
        dados.cliente?.email ??
        null,

      nome_cliente:
        dados.nome ??
        dados.cliente?.nome ??
        null,

      assunto,
      corpo_email: corpo,
      status: "pronto_para_envio"
    }
  };
});
